contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // sendAmount: Ether forwarded to c.go
    function run(uint sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount, "insufficient balance to send");

        // Record observable pre-call values
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        // Call c.go forwarding sendAmount and observe whether it reverted
        bool reverted;
        c.go{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: the owner never changes to a different address, and the contract's balance
        // after the call is not greater than before the call (i.e., go cannot increase c's balance).
        // This asserts these hold for all inputs and call outcomes.
        assert(c.owner() == ownerBefore && address(c).balance <= balanceBefore);
    }

    receive() external payable {}
}

